'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
const {environment,examples}=require('./native-fixtures-20261003.cjs');
const root=path.resolve(__dirname,'..'),dir=path.join(root,'docs/qa-single-paste27');fs.mkdirSync(dir,{recursive:true});
const report={release:'20261015paste27',cases:[],failures:[],scope:'Real local exporters and content fidelity; no external AI account or forecast accuracy claim.'};
const env=environment(),c=env.ctx;['tarot-foundation','prompt-brief','prompt-packet'].forEach(env.load);const x=examples(c),P=c.JYPromptPacket;
function test(name,fn){try{const detail=fn();report.cases.push({name,status:'passed',...detail});console.log('PASS '+name);}catch(e){report.failures.push({name,message:e.message,characters:e.characters,blocks:e.blocks});console.error('FAIL '+name+': '+e.message);}fs.writeFileSync(path.join(dir,'validation.json'),JSON.stringify(report,null,2));}
function validate(method,chart,q=x.q,options={}){const before=JSON.stringify(chart),body=P.build(method,chart,q,options),p=P.get(body);assert(p);assert.equal(JSON.stringify(chart),before,'source chart changed');assert.equal(p.deliveryMode,'single-message');assert.equal(p.parts.length,1);assert.equal(p.parts[0],body);assert.equal(p.contentChunks[0],body);assert(P.chars(body)<=12000);assert(P.utf8(body)<=28000);assert(body.includes(JSON.stringify(q)));assert.equal((body.match(/【解讀與查證規則】/g)||[]).length,1);assert(!body.includes('【本段內容開始】'));assert(!body.includes('【完整純文字分析提示詞】'));assert(body.includes('真實查閱'));assert(body.includes('不自稱真人親斷'));assert(p.readingData.sections.length);assert.equal(p.projection.completeCore,true);assert.equal(c.JYReadingWorkflow.readVerificationFacts({sourcePrompt:body}).status,'available');assert.equal(P.finish(body),body);assert.equal(P.exportPacket(body).fullPrompt,body);fs.writeFileSync(path.join(dir,'after-'+method+'.txt'),body);return {body,p,characters:P.chars(body),bytes:P.utf8(body)};}
for(const [method,chart]of Object.entries(x.charts))test(method+' real exporter',()=>{const p=validate(method,chart);return {characters:p.characters,bytes:p.bytes,notExpanded:p.p.projection.notExpanded};});
test('provided financial question retains both outcomes and exact wording',()=>{const q='我經濟壓力還是才會消失，我副業何時才能每月營業額淨賺10萬？',p=validate('vedic',x.v,q),tasks=p.p.readingData.requestCoverage[0].coverage.requirements.tasks;assert.equal(tasks.length,2);assert(p.body.includes(q));return {characters:p.characters};});
test('Vedic all twenty AV tables round-trip exactly; rescue checks remain explicit',()=>{const {body,p}=validate('vedic',x.v),av=p.readingData.sections.find(s=>s.label==='八分法所有分盤').data.vargas;const section=body.split('【AV原表：')[1].split('】\n')[1].split('\n\n【')[0];const rows=section.split('\n');assert.equal(rows.length,Object.keys(av).length);const order=['Sun','Moon','Mercury','Venus','Mars','Jupiter','Saturn'];for(const r of rows){const [d,sav,...bav]=r.split('/'),v=av[d.slice(1)];assert.deepEqual(sav.split(',').map(Number),JSON.parse(JSON.stringify(v.sav)));assert.equal(bav.length,7);bav.forEach((s,i)=>{assert.equal(s.length,12);assert.deepEqual([...s].map(Number),JSON.parse(JSON.stringify(v.bav[order[i]])));});}assert(body.includes('Phala7.26/29、是'));assert(body.includes('仍保留原強弱及近日'));return {tables:rows.length};});
test('two charts share one instruction block and retain both entire palace tables',()=>{const q='完整合讀這兩張本命盤與2026至2029年',body=P.buildMany([{method:'bazi',chart:x.b,label:'甲'},{method:'ziwei',chart:x.z,label:'乙'}],q),p=P.get(body);assert(P.chars(body)<=12000);assert.equal(p.parts.length,1);assert.equal((body.match(/【解讀與查證規則】/g)||[]).length,1);assert(body.includes('甲／四柱：'));assert(body.includes('乙／十二宮：'));assert.equal(p.readingData.sourceCoverage.readableRecords,2);return {characters:P.chars(body)};});
test('eighty explicit annual rows are never replaced by a top-N sample',()=>{const {body,p}=validate('ziwei',x.z,'請逐年分析2026年至2105年');const sections=p.readingData.sections,rows=[sections.find(s=>s.label==='運限疊宮').data.annual,...sections.find(s=>s.label==='明示年度流年').data];assert.equal(new Set(rows.map(r=>r.year)).size,80);for(let y=2026;y<=2105;y++)assert(body.includes('\n'+y+'/'),'missing year '+y);return {years:80,characters:P.chars(body)};});
test('provided Yijing cast retains selected text and all six moving statuses',()=>{const chart=c.JYYijingCore.calculate({values:[7,6,9,6,8,8],question:'今年我財運如何？'}),{body,p}=validate('yijing',chart,'今年我財運如何？');assert(body.includes('7,6,9,6,8,8'));assert(body.includes('歸妹：征凶，无攸利。'));assert(body.includes('明夷：利艱貞。'));assert(body.includes('主悔'));const sections=p.readingData.sections,raw=sections.find(s=>s.label==='完整起卦與六爻').data;assert.equal(raw.original.number,36);assert.equal(raw.changed.number,54);return {characters:P.chars(body)};});
test('full production OOTK preserves every active order, counting step and pair',()=>{const payload=JSON.parse(fs.readFileSync(path.join(dir,'ootk-fixture.json'))),q=payload.question,{body,p}=validate('ootk',payload,q),native=p.readingData.sections.find(s=>s.label==='本次完整操作與牌籤作用').data;assert.equal(native.operations.length,5);for(const op of native.operations){const o=op.data,block=body.split('【'+op.operation+'完整輪次】\n')[1].split('\n\n【')[0];assert(block);const line=k=>block.split('\n').find(r=>r.startsWith(k+'='))?.slice(k.length+1);const ids=line('牌序').split(',').map(v=>Number(v.replace(/[↑↓?]$/,'')));assert.deepEqual(ids,JSON.parse(JSON.stringify(o.activeCards.map(p=>p.id))));assert.equal(line('計數').split(';').filter(Boolean).length,o.countingPath.length);assert.equal(line('配對').split(';').filter(Boolean).length,o.pairs.length);assert.equal(line('尊貴').split(';').filter(Boolean).length,o.dignities.length);}return {operations:5,characters:P.chars(body)};});
test('Unicode or oversized old exports fail before clipboard and never split',()=>{assert.throws(()=>P.build('tarot',x.tarot,'😀'.repeat(12000)),e=>e.code==='SINGLE_PROMPT_CORE_OVER_BUDGET');assert.throws(()=>P.finish('甲'.repeat(12000)),e=>/OVER_BUDGET/.test(e.code));assert.throws(()=>P.split('甲'.repeat(12000)),e=>/OVER_BUDGET/.test(e.code));assert.equal(P.split('😀'.repeat(100))[0],'😀'.repeat(100));});
test('standalone prompt-brief and prompt-packet carry the same canonical runtime',()=>{const source=fs.readFileSync(path.join(root,'JS/prompt-single-paste.js'),'utf8').replace(/\n  if\(typeof module[^\n]+\n/,'\n');for(const file of ['prompt-brief.js','prompt-packet.js']){const text=fs.readFileSync(path.join(root,'JS',file),'utf8');assert(text.includes(source));assert.equal(text,fs.readFileSync(path.join(root,file),'utf8'));}});
report.status=report.failures.length?'failed':'passed';fs.writeFileSync(path.join(dir,'validation.json'),JSON.stringify(report,null,2));console.log(JSON.stringify({status:report.status,passed:report.cases.length,failed:report.failures.length}));if(report.failures.length)process.exitCode=1;
